    Queue<Integer> queue = new LinkedList<>();
    // Create a hash set to keep track of the nodes we have visited
    Set<Integer> visited = new HashSet<>();
    // Create a hash set to keep track of the apples we have collected
    Set<Integer> apples = new HashSet<>();
    // Create a hash map to keep track of the nodes and their neighbors
    Map<Integer, List<Integer>> neighbors = new HashMap<>();
    // Initialize the queue with the starting node
    queue.add(0);
    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current node from the queue
        int current = queue.remove();
        // Mark the current node as visited
        visited.add(current);
        // If the current node has an apple, add it to the set of apples
        if (hasApple[current]) {
            apples.add(current);
        }
        // Loop through the neighbors of the current node
        for (int neighbor : neighbors.get(current)) {
            // If the neighbor has not been visited, add it to the queue
            if (!visited.contains(neighbor)) {
