public int findMinFibonacciNumbers(int k) {
    // We keep track of the minimum number of Fibonacci numbers needed to sum up to k
    int minNumFib = 0;
    // We keep track of the current Fibonacci number we are considering
    int currentFib = 1;
    // We keep track of the previous Fibonacci number
    int previousFib = 0;
    while (currentFib < k) {
        // If the current Fibonacci number is greater than or equal to k, we need to
        // add the previous Fibonacci number to the sum and increase the minimum number
        // of Fibonacci numbers needed
        if (currentFib >= k) {
            minNumFib++;
            currentFib = previousFib;
        }
        // We increment the previous Fibonacci number
        previousFib = currentFib;
        // We calculate the next Fibonacci number
        currentFib = previousFib + currentFib;
    }
    // If the last Fibonacci number is less than k, we need to add 1 to the minimum number
    // of Fibonacci numbers needed
    if (currentFib == k) {
        minNumFib++;
    }
    // Return the minimum number of Fibonacci numbers needed to sum up to k
    return minNumFib;
}

