public String getSmallestString(int n, int k) {
  if (n == 1) {
    return String.valueOf((char) (k + 'a' - 1));
  }

  List<Character> chars = new ArrayList<>();
  for (int i = 'a'; i <= 'z'; i++) {
    chars.add((char) i);
  }

  for (int i = 2; i < n; i++) {
    int newSum = k % 26;
    k /= 26;
    if (k == 0) {
      k = newSum;
    }
    chars.add((char) (newSum + 'a' - 1));
  }

  Collections.sort(chars);
  StringBuilder sb = new StringBuilder();
  for (char c : chars) {
    sb.append(c);
  }
  return sb.toString();
}

