        maxArea = Math.max(maxArea, currentHeight * currentWidth);
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    // Calculate the number of elements in the matrix
    int n = mat.length * mat[0].length;

    // Initialize an array to hold the diagonal elements
    int[] diag = new int[n];

    // Initialize two pointers, one for the row and one for the column
    int row = 0, col = 0;

    // Iterate through the matrix
    for (int i = 0; i < n; i++) {
        // Set the current element at the current row and column
        diag[i] = mat[row][col];

        // Increment the column and wrap around if necessary
        col = (col + 1) % mat[0].length;
        if (col == 0) {
            row++;
        }
    }

    // Return the diagonal elements
    return diag;
}

public static int findSmallestInteger(int n) {
    String digits = String.valueOf(n);
    int[] digitArr = new int[digits.length()];
    for (int i = 0; i < digits.length(); i++) {
        digitArr[i] = digits.charAt(i) - '0';
    }

    Arrays.sort(digitArr);

    for (int i = 0; i < digitArr.length; i++) {
        digits = digits.replace(String.valueOf(digitArr[i]), "");
    }

    try {
        return Integer.parseInt(digits) + 1;
    } catch (NumberFormatException e) {
        return -1;
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        String number = Integer.toString(i);
        if (number.length() == n) {
            result.add(number);
        }
        else if (number.length() < n) {
            String leftPadding = "0".repeat(n - number.length());
            result.add(leftPadding + number);
        }
        else {
            String rightPadding = "0".repeat(number.length() - n);
            result.add(number + rightPadding);
        }
    }
    return result;
}

public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        return false;
    }

    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];

    int det = (x1 - x2) * (y1 - y3) - (x1 - x3) * (y1 - y2);

    return det != 0;
}

public static int findNthUglyNumber(int n) {
    int[] dp = new int[n + 1];
    dp[1] = 1;
    int p2 = 1, p3 = 1, p5 = 1;
    for (int i = 2; i <= n; i++) {
        int min = Math.min(dp[p2] * 2, Math.min(dp[p3] * 3, dp[p5] * 5));
        dp[i] = min;
        if (min == dp[p2] * 2) {
            p2++;
        }
        if (min == dp[p3] * 3) {
            p3++;
        }
        if (min == dp[p5] * 5) {
            p5++;
        }
    }
    return dp[n];
}

public static int calculateEnergy(String s) {
    int energy = 0;
    int maxLength = 0;
    for (int i = 0; i < s.length(); i++) {
        int length = 0;
        char currentChar = s.charAt(i);
        for (int j = i; j < s.length(); j++) {
            if (s.charAt(j) == currentChar) {
                length++;
            } else {
                break;
            }
        }
        if (length > maxLength) {
            maxLength = length;
        }
    }
    energy = maxLength;
    return energy;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        result.add(i);
    }
    result.sort((a, b) -> a.toString().compareTo(b.toString()));
    return result;
}

public static int calculateUniqueSum(int[] nums) {
        int sum = 0;
        // Keep track of unique elements in a set
        Set<Integer> unique = new HashSet<>();
        for (int num : nums) {
            // If the element is not in the set, add it and calculate the sum
            if (!unique.contains(num)) {
                unique.add(num);
                sum += num;
            }
        }
        return sum;
    }

public static int minPerfectSquareSum(int n) {
    // Initialize a list to store the perfect square numbers
    List<Integer> perfectSquares = new ArrayList<>();

    // Initialize a variable to store the minimum number of perfect square numbers
    int minPerfectSquares = 0;

    // Iterate from 1 to n
    for (int i = 1; i <= n; i++) {
        // Check if the current number is a perfect square
        if (isPerfectSquare(i)) {
            // If it is, add it to the list of perfect square numbers
            perfectSquares.add(i);
            // Increase the minimum number of perfect square numbers
            minPerfectSquares++;
        }
    }

    // Return the minimum number of perfect square numbers
    return minPerfectSquares;
}

public static String reverseWords(String s) {
   String[] words = s.split(" ");
   String result = "";

   for (int i = 0; i < words.length; i++) {
      String word = words[i];
      StringBuilder reversedWord = new StringBuilder(word);
      reversedWord.reverse();
      result += reversedWord.toString() + " ";
   }

   return result.trim();
}
